fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let freqs = [262, 294, 330, 349, 392, 440, 494];
    let names = [67, 68, 69, 70, 71, 65, 66];
    let kw: i32 = w / 7;
    let ky: i32 = h / 2 - 80;
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut cur: i32 = -1;
    if py >= ky && py < ky + 160 {
        cur = px / kw;
        if cur > 6 { cur = 6; }
    }
    if down == 1 && prev == 0 && cur >= 0 {
        host::audio::tone(freqs[cur], 160, 3);
    }
    host::display::state_set(0, down);
    host::display::clear(0x101010);
    let mut i: i32 = 0;
    while i < 7 {
        let mut c: i32 = 0xe8e8e8;
        if down == 1 && i == cur { c = 0x88ccff; }
        host::display::fill_rect(i * kw + 1, ky, kw - 2, 160, c);
        host::display::draw_char(i * kw + kw / 2 - 3, ky + 130, names[i], 0x303030, 1);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "TAP A KEY", 0x808080, 1);
    host::display::present();
}
